from random import choice, seed

def generate_grid(rows, cols, colors=['Red', 'Green', 'Blue', 'Yellow', 'Purple'], rng_seed=None):
    """
    Generate a grid (list of lists) of colors for the given number of rows
    and columns.

    Each cell alternates between two sources:
      - Even-indexed cells (counting across the whole grid row by row)
        take the next color from a cyclic sequence of the colors list.
      - Odd-indexed cells take a random color chosen from the same list.

    Args:
        rows (int): Number of rows in the grid.
        cols (int): Number of columns in the grid.
        colors (list): List of color names to use (default 5 colors).
        rng_seed: Optional seed for the random number generator to make
            the random choices reproducible.

    Returns:
        list[list[str]]: The generated grid, one sublist per row.
    """
    if rng_seed is not None:
        seed(rng_seed)

    color_cycle = cycle(colors)
    grid = []
    cell_count = 0  # global cell index across the whole grid

    for _ in range(rows):
        row = []
        for _ in range(cols):
            if cell_count % 2 == 0:
                # Cyclic sequence of colors
                row.append(next(color_cycle))
            else:
                # Random color from the same list
                row.append(choice(colors))
            cell_count += 1
        grid.append(row)

    return grid
